<?php
require 'db.php'; session_start(); require 'includes.php';
if (($_SESSION['user_role'] ?? '') !== 'admin') { header('Location: login.php'); exit; }
$studentId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$studentId) { header('Location: admin_students.php'); exit; }
$sql = "SELECT u.*, req.roll_no, req.status AS request_status, req.payment_status, req.final_amount, r.room_number, r.room_type, r.hostel_block, r.floor FROM users u LEFT JOIN room_requests req ON req.id=(SELECT rr.id FROM room_requests rr WHERE rr.user_id=u.id ORDER BY FIELD(rr.status,'Approved','Pending','Rejected'),rr.created_at DESC LIMIT 1) LEFT JOIN rooms r ON r.id=req.room_id WHERE u.id=? AND u.role='student' LIMIT 1";
$stmt=$conn->prepare($sql); $stmt->bind_param('i',$studentId); $stmt->execute(); $student=$stmt->get_result()->fetch_assoc(); $stmt->close();
if (!$student) { flash('error','Student profile not found.'); header('Location: admin_students.php'); exit; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($student['name'])?> | StaySpace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/app.css"></head><body><div class="app"><aside class="sidebar"><div class="brand"><i class="fa-solid fa-building-shield"></i><span>StaySpace</span></div><div class="nav-label">ADMIN CONTROL</div><nav class="nav"><a href="admin_dashboard.php"><i class="fa-solid fa-chart-pie"></i><span>Dashboard</span></a><a href="admin_rooms.php"><i class="fa-solid fa-bed"></i><span>Room management</span></a><a class="active" href="admin_students.php"><i class="fa-solid fa-users"></i><span>Student management</span></a><a class="logout" href="logout.php"><i class="fa-solid fa-arrow-right-from-bracket"></i><span>Sign out</span></a></nav></aside><main class="content"><header class="topbar"><div><h1>Student profile</h1><p class="eyebrow">Student, accommodation and payment details.</p></div><a class="btn btn-light" href="admin_students.php"><i class="fa-solid fa-arrow-left"></i> Back to students</a></header><section class="card profile-hero"><img class="profile-avatar" src="<?=avatar_url($student['avatar_path'],$student['name'])?>" alt="<?=e($student['name'])?> profile picture"><div><h2><?=e($student['name'])?></h2><p class="muted"><?=e($student['email'])?></p><span class="badge <?=($student['request_status']?status_class($student['request_status']):'pending')?>"><?=e($student['request_status']?:'No active request')?></span></div></section><div class="grid-2"><section class="card"><div class="card-heading"><h2>Student details</h2></div><dl class="profile-details"><div><dt>Full name</dt><dd><?=e($student['name'])?></dd></div><div><dt>Roll / student ID</dt><dd><?=e($student['roll_no']?:'Not provided')?></dd></div><div><dt>Branch</dt><dd><?=e($student['branch']?:'Not provided')?></dd></div><div><dt>Phone</dt><dd><?=e($student['phone_number']?:'Not provided')?></dd></div><div><dt>Emergency contact</dt><dd><?=e($student['emergency_contact']?:'Not provided')?></dd></div><div><dt>Parent / guardian</dt><dd><?=e($student['fathers_name']?:$student['mothers_name']?:'Not provided')?></dd></div><div class="profile-wide"><dt>Permanent address</dt><dd><?=e($student['permanent_address']?:'Not provided')?></dd></div></dl></section><section class="card"><div class="card-heading"><h2>Accommodation & fees</h2></div><dl class="profile-details"><div><dt>Allocated room</dt><dd><?=e($student['room_number']?:'Not allocated')?></dd></div><div><dt>Hostel block</dt><dd><?=e($student['hostel_block']?:'Not assigned')?></dd></div><div><dt>Room type</dt><dd><?=e($student['room_type']?:'Not assigned')?></dd></div><div><dt>Floor</dt><dd><?=e($student['floor']?:'Not assigned')?></dd></div><div><dt>Fee status</dt><dd><span class="badge <?=($student['payment_status']==='Paid'?'paid':'unpaid')?>"><?=e($student['payment_status']?:'Not due')?></span></dd></div><div><dt>Fee amount</dt><dd><?=($student['final_amount']!==null?'₹'.number_format((float)$student['final_amount']):'—')?></dd></div></dl></section></div></main></div><script src="assets/js/app.js"></script></body></html>
